// #573: the long topic docs of docs/agents/ split into one file per subtopic, as engine.md already is:
// `npm run docs` builds docs/agents/<topic>.md from docs/agents/<topic>/*.md for every topic folder
// (each file's first heading and summary line), `--check` fails on a stale index or a subtopic file
// without its heading and summary line, and a topic or subtopic file over the size limit (~200 lines)
// is listed (generated files exempt).
// Seams: scripts/docs.js's main (`npm run docs`, `--check`) and checkDocs, on the real repository or
// on a temporary copy of what the generator reads (skills/, docs/, README.md).
const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('fs');
const os = require('os');
const path = require('path');
const { execFileSync } = require('child_process');

const root = path.join(__dirname, '..');
const AGENTS_DOCS = path.join(root, 'docs', 'agents');
const read = (p) => fs.readFileSync(p, 'utf8').replace(/\r\n/g, '\n');
const load = () => require('../scripts/docs.js');
const mdFiles = (dir) => (fs.existsSync(dir) ? fs.readdirSync(dir).filter((f) => f.endsWith('.md')).sort() : []);
const lineCount = (text) => text.replace(/\n$/, '').split('\n').length;
const SPLIT_TOPICS = ['renderer', 'testing', 'storage'];
const LIMIT = 200;

function tmpRoot(t) {
  const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'docs-topics-'));
  t.after(() => fs.rmSync(tmp, { recursive: true, force: true }));
  fs.cpSync(path.join(root, 'skills'), path.join(tmp, 'skills'), { recursive: true });
  fs.cpSync(path.join(root, 'docs'), path.join(tmp, 'docs'), { recursive: true });
  fs.copyFileSync(path.join(root, 'README.md'), path.join(tmp, 'README.md'));
  return tmp;
}

function writeTopic(tmp, topic, files) {
  const dir = path.join(tmp, 'docs', 'agents', topic);
  fs.mkdirSync(dir, { recursive: true });
  for (const [name, content] of Object.entries(files)) fs.writeFileSync(path.join(dir, name), content);
}

// main(argv, tmp) with what it prints (errors and warnings) captured as one string
function runMain(argv, tmp) {
  const { main } = load();
  const out = [];
  const saved = { error: console.error, warn: console.warn, log: console.log };
  const capture = (...args) => { out.push(args.map(String).join(' ')); };
  console.error = capture; console.warn = capture; console.log = capture;
  try {
    const code = main(argv, tmp);
    return { code, output: out.join('\n').replace(/\\/g, '/') };
  } finally {
    Object.assign(console, saved);
  }
}

const topicBody = (title, summary, body = 'Body text of the subtopic.') => `# ${title}\n\n${summary}\n\n## Details\n\n${body}\n`;

// --- the generator, on a temporary root ------------------------------------------------------------

test('npm run docs builds an index for every docs/agents/<topic>/ folder, not only engine/', (t) => {
  const tmp = tmpRoot(t);
  writeTopic(tmp, 'zz-alpha', {
    'b-two.md': topicBody('Two title', 'Two summary.'),
    'a-one.md': topicBody('One title', 'One summary.', 'Alpha body must not be copied.'),
  });
  writeTopic(tmp, 'zz-beta', { 'only.md': topicBody('Only title', 'Only summary.') });

  assert.equal(runMain(['--check'], tmp).code, 1, '--check should fail while the new indexes are missing');
  assert.equal(runMain([], tmp).code, 0);
  const after = runMain(['--check'], tmp);
  assert.equal(after.code, 0, `--check should pass once the indexes are written: ${after.output}`);

  const alphaFile = path.join(tmp, 'docs', 'agents', 'zz-alpha.md');
  const betaFile = path.join(tmp, 'docs', 'agents', 'zz-beta.md');
  assert.equal(fs.existsSync(alphaFile), true, 'docs/agents/zz-alpha.md should be generated');
  assert.equal(fs.existsSync(betaFile), true, 'docs/agents/zz-beta.md should be generated');

  const alpha = read(alphaFile);
  assert.match(alpha.split('\n').find((l) => l.trim()) || '', /^# /, 'the index starts with a heading');
  assert.match(alpha, /<!-- Generated by `npm run docs` from docs\/agents\/zz-alpha\/\*\.md[^\n]*edit or add a topic file, not this index/);
  const items = alpha.split('\n').filter((l) => l.startsWith('- '));
  assert.equal(items.length, 2);
  assert.match(items[0], /^- \[One title\]\((\.\/)?zz-alpha\/a-one\.md\): One summary\.$/);
  assert.match(items[1], /^- \[Two title\]\((\.\/)?zz-alpha\/b-two\.md\): Two summary\.$/);
  assert.doesNotMatch(alpha, /Alpha body must not be copied/);

  const beta = read(betaFile);
  assert.match(beta, /^- \[Only title\]\((\.\/)?zz-beta\/only\.md\): Only summary\.$/m);
  assert.doesNotMatch(beta, /zz-alpha/);
});

test('--check names a topic index that is out of date with its subtopic files', (t) => {
  const tmp = tmpRoot(t);
  writeTopic(tmp, 'zz-alpha', { 'a-one.md': topicBody('One title', 'One summary.') });
  assert.equal(runMain([], tmp).code, 0);
  writeTopic(tmp, 'zz-alpha', { 'a-one.md': topicBody('One title', 'A changed summary.') });

  const { code, output } = runMain(['--check'], tmp);
  assert.equal(code, 1);
  assert.match(output, /zz-alpha\.md/);
});

test('--check fails on a subtopic file without a first heading or without a summary line, naming the file', (t) => {
  const tmp = tmpRoot(t);
  writeTopic(tmp, 'zz-alpha', {
    'a-good.md': topicBody('Good title', 'Good summary.'),
    'b-no-heading.md': 'Just prose, no heading.\n',
    'c-no-summary.md': '# No summary title\n\n## Straight to a sub-heading\n\nText.\n',
  });
  runMain([], tmp);

  const { code, output } = runMain(['--check'], tmp);
  assert.equal(code, 1);
  assert.match(output, /b-no-heading\.md/);
  assert.match(output, /c-no-summary\.md/);
  assert.doesNotMatch(output, /a-good\.md/);
});

test('the size check lists a topic or subtopic file over 200 lines, never a generated file or a short one', (t) => {
  const tmp = tmpRoot(t);
  const long = (title) => `# ${title}\n\nA summary line.\n\n${Array.from({ length: 240 }, (_, i) => `Line ${i + 1}.`).join('\n')}\n`;
  fs.writeFileSync(path.join(tmp, 'docs', 'agents', 'zz-long-topic.md'), long('Long topic'));
  writeTopic(tmp, 'zz-alpha', {
    'a-short.md': topicBody('Short title', 'Short summary.'),
    'b-long-subtopic.md': long('Long subtopic'),
  });
  runMain([], tmp); // writes the indexes and the generated files (code-map.md, test-map.md, channels.md) too

  const { code, output } = runMain(['--check'], tmp);
  assert.equal(code, 0, 'the size rule is a warning until every long doc is split (decisions.md): it never fails --check');
  assert.match(output, /zz-long-topic\.md/, 'a top-level topic over the limit is listed');
  assert.match(output, /b-long-subtopic\.md/, 'a subtopic over the limit is listed');
  assert.doesNotMatch(output, /a-short\.md/);
  for (const generated of ['code-map.md', 'test-map.md', 'channels.md', 'field-reference.md']) {
    assert.doesNotMatch(output, new RegExp(generated.replace('.', '\\.')), `${generated} is generated: exempt`);
  }
});

// --- the split, on the real repository -------------------------------------------------------------

for (const topic of SPLIT_TOPICS) {
  test(`docs/agents/${topic}.md is a generated index over docs/agents/${topic}/, each subtopic short and with a heading and summary line`, () => {
    const dir = path.join(AGENTS_DOCS, topic);
    const files = mdFiles(dir);
    assert.ok(files.length >= 2, `docs/agents/${topic}/ should hold one file per subtopic (found ${files.length})`);

    const index = read(path.join(AGENTS_DOCS, `${topic}.md`));
    assert.match(index, new RegExp(`<!-- Generated by \`npm run docs\` from docs/agents/${topic}/\\*\\.md`));
    const unlisted = files.filter((f) => !index.includes(`(${topic}/${f})`) && !index.includes(`(./${topic}/${f})`));
    assert.deepEqual(unlisted, []);
    const nonBlank = index.split('\n').filter((l) => l.trim()).length;
    assert.ok(nonBlank <= files.length + 15, `${topic}.md should be a short index (${nonBlank} non-blank lines)`);

    const bad = [];
    for (const f of files) {
      const lines = read(path.join(dir, f)).split('\n');
      const h = lines.findIndex((l) => /^#+\s/.test(l));
      const summary = h < 0 ? undefined : lines.slice(h + 1).find((l) => l.trim());
      if (h < 0 || !summary || /^#+\s/.test(summary)) bad.push(`${f}: no first heading and summary line`);
      if (lines.length > LIMIT + 1) bad.push(`${f}: ${lines.length} lines (limit ${LIMIT})`);
    }
    assert.deepEqual(bad, []);
  });
}

test('the split indexes are up to date (npm run docs --check reports none of them)', () => {
  const { checkDocs } = load();
  const stale = checkDocs(root).filter((p) => SPLIT_TOPICS.some((topic) => p.replace(/\\/g, '/').includes(`docs/agents/${topic}.md`)));
  assert.deepEqual(stale, []);
});

// The warning list, pinned: a doc that grows past the limit shows up here, not only in --check's
// output; split it (or record why) instead of adding it to the list.
test('the docs over 200 lines are only the three not split yet', () => {
  const { oversizedDocs } = load();
  assert.deepEqual(oversizedDocs(root).map((d) => d.file).sort(), [
    'docs/agents/capabilities.md',
    'docs/agents/decisions.md',
    'docs/agents/engine/gates-and-run-end.md',
  ]);
});

test('engine/agents-and-steps.md is split:no engine topic file of that name over 200 lines', () => {
  const file = path.join(AGENTS_DOCS, 'engine', 'agents-and-steps.md');
  if (!fs.existsSync(file)) return;
  const n = lineCount(read(file));
  assert.ok(n <= LIMIT, `docs/agents/engine/agents-and-steps.md has ${n} lines (limit ${LIMIT})`);
});

// --- links and anchors after the split ---------------------------------------------------------------

// GitHub's heading anchors: lower case, punctuation dropped, spaces to hyphens, duplicates numbered
function anchorsOf(file) {
  const seen = new Map();
  const anchors = new Set();
  const text = read(file).replace(/```[\s\S]*?```/g, '');
  for (const m of text.matchAll(/^#{1,6}\s+(.+?)\s*#*\s*$/gm)) {
    const base = m[1].toLowerCase().replace(/[^\p{L}\p{N}\s_-]/gu, '').trim().replace(/\s/g, '-');
    const n = seen.get(base) || 0;
    seen.set(base, n + 1);
    anchors.add(n ? `${base}-${n}` : base);
  }
  for (const m of text.matchAll(/<a\s+(?:name|id)="([^"]+)"/g)) anchors.add(m[1]);
  return anchors;
}

test('no link into docs/agents/ from any tracked Markdown file is broken, its #anchor included', () => {
  const tracked = execFileSync('git', ['ls-files', '*.md'], { cwd: root, encoding: 'utf8' })
    .split('\n').map((l) => l.trim()).filter(Boolean)
    .filter((f) => !/(^|\/)node_modules\//.test(f) && fs.existsSync(path.join(root, f)));
  const agentsDir = `${AGENTS_DOCS}${path.sep}`;
  const broken = [];
  for (const rel of tracked) {
    const file = path.join(root, rel);
    const text = read(file).replace(/```[\s\S]*?```/g, '').replace(/`[^`\n]*`/g, '');
    for (const m of text.matchAll(/\]\(([^)\s]+)(?:\s+"[^"]*")?\)/g)) {
      const [target, anchor] = m[1].split('#');
      if (/^[a-z]+:/i.test(m[1])) continue;
      const resolved = target ? path.resolve(path.dirname(file), decodeURI(target)) : file;
      if (!resolved.startsWith(agentsDir) || !resolved.endsWith('.md')) continue;
      if (!fs.existsSync(resolved)) { broken.push(`${rel} -> ${m[1]} (no such file)`); continue; }
      if (anchor && !anchorsOf(resolved).has(decodeURI(anchor).toLowerCase())) broken.push(`${rel} -> ${m[1]} (no such anchor)`);
    }
  }
  assert.deepEqual(broken, []);
});
